    if m > 2 * n or m % 2 != 0:
        return 0

    dp = [[[[[0] * 2 for _ in range(m + 2)] for _ in range(n + 1)] for _ in range(n + 1)] for _ in range(n + 1)]

    dp[0][0][0][0][0] = 1

    for i in range(2 * n):
        x, y, z, w, u = i // 2, (i - 1) // 2, (i - 2) // 2, (i - 3) // 2, (i - 4) // 2
        for l in range(x + 1):
            for r in range(y + 1):
                for p in range(z + 1):
                    for q in range(w + 1):
                        for v in range(u + 1):
                            if i < m and s[i] == '(':
