                            if i < m and s[i] == ')':
                                dp[l][r + 1][p][q][v] += dp[l][r][p][q][v]
                            if l > 0:
                                dp[l - 1][r][p + 1][q][v] += dp[l][r][p][q][v]
                            if r > 0:
                                dp[l][r - 1][p][q + 1][v] += dp[l][r][p][q][v]
                            if p > 0:
                                dp[l][r][p - 1][q + 1][v] += dp[l][r][p][q][v]
                            if q > 0:
                                dp[l][r][p][q - 1][v + 1] += dp[l][r][p][q][v]
                            dp[l][r][p][q][v] %= MOD

    result = 0
    for l in range(n + 1):
        for r in range(n + 1):
            for p in range(n + 1):
                for q in range(n + 1):
                    for v in range(n + 1):
                        if l + r == n and p + q == n and v == 0:
