def count_regular_sequences(n, s):
    from collections import deque

    def valid(subseq):
        balance = 0
        for char in subseq:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    s_length = len(s)
    dp = [0] * (s_length + 1)
    dp[0] = 1

    for i in range(1, 2*n + 1):
        new_dp = [0] * (s_length + 1)
        for j in range(i + 1):
            if j >= s_length and valid(s):
                new_dp[j] = dp[j-1]
            elif j < s_length and valid(s[:j]):
                new_dp[j] = dp[j-1]
            if i - j >= s_length and valid(s[::-1][:i-j]):
                new_dp[j] += dp[i-j-1]
            new_dp[j] %= MOD
        dp = new_dp

    return dp[s_length]

