    dp = [[0] * (m + 1) for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(m + 1):
        for j in range(i + 1):
            if i > 0:
                dp[i][j] += dp[i - 1][j]
            if j > 0:
                dp[i][j] += dp[i][j - 1]
            if i > 0 and j > 0:
                dp[i][j] -= dp[i - 1][j - 1]
            if i < m:
                dp[i + 1][j] += dp[i][j]

    def add(a, b):
        return (a + b) % MOD

    def sub(a, b):
        return (a - b + MOD) % MOD

    def mul(a, b):
        return (a * b) % MOD

    def inv(x):
        return pow(x, MOD - 2, MOD)

    def catalan(n):
        return mul(inv(mul(n + 1, n + 2)), mul(n + 1, 2))

    total_ways = mul(catalan(2 * n), inv(catalan(n)))
    invalid_ways = 0

    for i in range(m + 1):
        invalid_ways = add(invalid_ways, mul(dp[i][i], mul(catalan(n + m - i), inv(catalan(n - i))))))

    return sub(total_ways, invalid_ways)

