    dp = [[[[[0]*3 for _ in range(3)] for _ in range(3)] for _ in range(n*2+1)] for _ in range(n*2+1)]

    def dfs(i, j, left_count, right_count, s_index):
        if i == n*2 or j == len(s):
            return 1 if i == j and left_count == right_count else 0

        if dp[i][j][left_count][right_count][s_index] != -1:
            return dp[i][j][left_count][right_count][s_index]

        result = 0
        if s[s_index] == '(':
            result += dfs(i + 1, j, left_count + 1, right_count, s_index + 1)
        elif s[s_index] == ')':
            result += dfs(i, j + 1, left_count, right_count + 1, s_index + 1)

        if left_count < right_count or left_count > n:
            result += dfs(i, j, left_count, right_count, s_index + 1)

        dp[i][j][left_count][right_count][s_index] = result % mod
        return result

    dp[-1][-1][0][0][len(s)] = 1
    for k in range(n*2):
        for l in range(len(s)):
            for m in range(3):
                for o in range(3):
                    for p in range(3):
                        if dp[k][l][m][o][p] != -1:
                            if k < n*2:
                                dp[k+1][l][m+1][o][p] += dp[k][l][m][o][p]
                                dp[k+1][l][m+1][o][p] %= mod
                            if l < len(s):
                                dp[k][l+1][m][o+1][p] += dp[k][l][m][o][p]
                                dp[k][l+1][m][o+1][p] %= mod

