def count_regular_bracket_sequences(n, s):
    def dp(i, j, balance):
        if i == len(s):
            return balance == 0
        if balance < 0 or balance > 2 * (len(s) - i):
            return 0
        key = (i, j, balance)
        if key in memo:
            return memo[key]
        result = 0
        if s[i] == '(':
            result += dp(i + 1, j + 1, balance + 1)
        elif s[i] == ')':
            result += dp(i + 1, j + 1, balance - 1)
        else:
            result = (result + dp(i + 1, j + 1, balance) +
                      dp(i + 1, j, balance + 1) +
                      dp(i + 1, j, balance - 1))
        memo[key] = result % MOD
        return result % MOD

    def catalan_number(n):
        C = [0] * (n + 1)
        C[0] = 1
        for i in range(1, n + 1):
            for j in range(i, -1, -1):
                C[j] = (C[j] + C[j - 1]) % MOD
        return C[n]

    m = len(s)
    if m > 2 * n:
        return 0

    left_catalan = catalan_number(n - m)
    right_catalan = catalan_number(m)
    total_catalan = left_catalan * right_catalan % MOD

    memo = {}
    result = dp(0, 0, 0)

    return result * total_catalan % MOD

